// InEditMode keeps the app router from stealing keys the view needs — a target
// can contain ':', esc must reach the run to cancel it, and esc must close the
// details rather than the view.
func TestInEditModeCoversTheStatesThatNeedKeys(t *testing.T) {
	m := newTestModel(t)

	m.focusedField = fieldTarget
	if !m.InEditMode() {
		t.Error("InEditMode() is false on the target field")
	}
	m.focusedField = fieldPing
	if m.InEditMode() {
		t.Error("InEditMode() is true on a checkbox, which needs no character keys")
	}

	if !runningModel(t, "example.com", "Ping").InEditMode() {
		t.Error("InEditMode() is false while running, so esc would not reach the cancel")
	}
	if !feed(t, resultsModel(t), testutil.Key("enter")).InEditMode() {
		t.Error("InEditMode() is false in the details, so esc would close the view instead")
	}
	if resultsModel(t).InEditMode() {
		t.Error("InEditMode() is true on the results table, which takes no text")
	}
}

// The topology tab takes no text, so a bare ":" reaches the router there
// whatever the topology is doing. The view used to carry an AllowCommandMode()
// that claimed to unlock ":" once the data had arrived; it could never fire,
// because InEditMode() is already false on this tab and the router only
// consulted it when InEditMode() was true. It is gone.
=== security ===
func TestInEditModeCoversEveryStateThatAnswersEsc(t *testing.T) {
	form := newTestModel(t)
	if form.InEditMode() {
		t.Error("InEditMode() is true on the form with a checkbox focused")
	}

	for _, field := range []int{1, 7, 10} {
		typing := newTestModel(t)
		typing.focusedField = field
		if !typing.InEditMode() {
			t.Errorf("InEditMode() is false while typing in field %d", field)
		}
	}

	for _, state := range []ViewState{StateScanning, StateResults, StateDetails} {
		m := newTestModel(t)
		m.state = state
		if !m.InEditMode() {
			t.Errorf("InEditMode() is false in state %v", state)
		}
	}

	withModal := scannedModel(t)
	withModal.switchTab(TabSecrets)
	if !feed(t, withModal, testutil.Key("i")).InEditMode() {
		t.Error("InEditMode() is false with a confirmation open")
	}
}

